// The local 3114 HUD supplies imported asset references. No runtime asset
// paths or shared font/material mutations are needed for this adapter.
public static void Set3114Presentation(TMP_FontAsset font, Material material)
{
    _3114Font = font;
    _3114Material = material;
}

private struct RectSnapshot
{
    public RectTransform Target;
    private Vector2 _anchorMin;
    private Vector2 _anchorMax;
    private Vector3 _anchoredPosition;
    private Vector2 _sizeDelta;
    private Vector2 _pivot;
    private Vector3 _localScale;
    private Quaternion _localRotation;

    public RectSnapshot(RectTransform rect)
    {
        Target = rect;
        _anchorMin = rect != null ? rect.anchorMin : Vector2.zero;
        _anchorMax = rect != null ? rect.anchorMax : Vector2.zero;
        _anchoredPosition = rect != null ? rect.anchoredPosition3D : Vector3.zero;
        _sizeDelta = rect != null ? rect.sizeDelta : Vector2.zero;
        _pivot = rect != null ? rect.pivot : Vector2.zero;
        _localScale = rect != null ? rect.localScale : Vector3.one;
        _localRotation = rect != null ? rect.localRotation : Quaternion.identity;
    }

    public void Restore()
    {
        if (Target == null) return;
        Target.anchorMin = _anchorMin;
        Target.anchorMax = _anchorMax;
        Target.pivot = _pivot;
        Target.sizeDelta = _sizeDelta;
        Target.anchoredPosition3D = _anchoredPosition;
        Target.localScale = _localScale;
        Target.localRotation = _localRotation;
    }
}

private static void ApplyNativeRect(RectTransform rect, Vector2 position, Vector2 size)
{
    if (rect == null) return;
    rect.anchorMin = Vector2.zero;
    rect.anchorMax = Vector2.one;
    rect.pivot = new Vector2(.5f, .5f);
    rect.sizeDelta = size;
    rect.anchoredPosition3D = new Vector3(position.x, position.y, 0f);
    rect.localScale = Vector3.one;
    rect.localRotation = Quaternion.identity;
}

private void Update3114Presentation()
{
    bool active = ReferenceHub.TryGetLocalHub(out var local) &&
        local.roleManager.CurrentRole is PlayerRoles.PlayableScps.Scp3114.Scp3114Role;
    if (!active)
    {
        Restore3114Presentation();
        return;
    }
    if (!_has3114Presentation)
    {
        if (_ragdollInspectText == null) return;
        _normalLabel = _ragdollInspectText;
        RectTransform labelRect = _normalLabel.rectTransform;
        RectTransform parentRect = labelRect.parent as RectTransform;
        _normalParentRect = new RectSnapshot(parentRect);
        _normalLabelRect = new RectSnapshot(labelRect);
        _normalFont = _normalLabel.font;
        _normalMaterial = _normalLabel.fontSharedMaterial;
        _normalParseCtrlCharacters = _normalLabel.parseCtrlCharacters;
        _normalRaycastDistance = _raycastDistance;
        _normalRaycastMask = _raycastMask;
        _has3114Presentation = true;

        // Current retail level2:18700 -> label14716/rect12607 and
        // BodyInspection rect12593. Both stretch; native center is
        // 122.5 reference pixels below center (61.3426% screen height).
        ApplyNativeRect(parentRect, Vector2.zero, Vector2.zero);
        ApplyNativeRect(labelRect, new Vector2(0f, -122.5f), new Vector2(-20f, -255f));
        _normalLabel.parseCtrlCharacters = false;
        _raycastDistance = 2.6f;
        // Native level2:18700 mask, resolved through verified layer names.
        _raycastMask = LayerMask.GetMask("Default", "Ragdoll", "CCTV", "Door");
    }
    // HUD.Init may supply the references after the role's first Update.
    if (_normalLabel != null)
    {
        if (_3114Font != null && _normalLabel.font != _3114Font)
            _normalLabel.font = _3114Font;
        if (_3114Material != null && _normalLabel.fontSharedMaterial != _3114Material)
            _normalLabel.fontSharedMaterial = _3114Material;
    }
}

private void Restore3114Presentation()
{
    if (!_has3114Presentation) return;
    _normalParentRect.Restore();
    _normalLabelRect.Restore();
    if (_normalLabel != null)
    {
        _normalLabel.font = _normalFont;
        _normalLabel.fontSharedMaterial = _normalMaterial;
        _normalLabel.parseCtrlCharacters = _normalParseCtrlCharacters;
    }
    _raycastDistance = _normalRaycastDistance;
    _raycastMask = _normalRaycastMask;
    _normalLabel = null;
    _has3114Presentation = false;
}

private void OnDisable() { Restore3114Presentation(); }
private void OnDestroy() { Restore3114Presentation(); }

private void Update()
{
    Update3114Presentation();
    if (!TryGetRagdoll(out BasicRagdoll ragdoll, out string coloredRoleName))
    {
        if (_ragdollInspectText != null)
            _ragdollInspectText.text = string.Empty;

